-- READ-ONLY exact-key aggregate; excludes protected Q1 2018; UTC bounds.
WITH c AS (SELECT CASE WHEN o.dateTime<1530403200 THEN '2018-Q2' WHEN o.dateTime<1538352000 THEN '2018-Q3' ELSE '2018-Q4' END AS utc_quarter,o.usUnits AS ou,w.usUnits AS wu,o.interval AS oi,w.interval AS wi,o.`rainBatteryStatus` AS old_rainBatteryStatus, w.`rainBatteryStatus` AS wh_rainBatteryStatus, o.`rainRate` AS old_rainRate, w.`rainRate` AS wh_rainRate, o.`referenceVoltage` AS old_referenceVoltage, w.`referenceVoltage` AS wh_referenceVoltage, o.`rxCheckPercent` AS old_rxCheckPercent, w.`rxCheckPercent` AS wh_rxCheckPercent, o.`soilMoist1` AS old_soilMoist1, w.`soilMoist1` AS wh_soilMoist1, o.`soilMoist2` AS old_soilMoist2, w.`soilMoist2` AS wh_soilMoist2, o.`soilMoist3` AS old_soilMoist3, w.`soilMoist3` AS wh_soilMoist3, o.`soilTemp1` AS old_soilTemp1, w.`soilTemp1` AS wh_soilTemp1, o.`soilTemp2` AS old_soilTemp2, w.`soilTemp2` AS wh_soilTemp2, o.`soilTemp3` AS old_soilTemp3, w.`soilTemp3` AS wh_soilTemp3 FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1522540800 AND o.dateTime<1546300800 AND r.dateTime IS NULL) SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'rainBatteryStatus' AS field_name,COUNT(*) AS source_only_rows,SUM(old_rainBatteryStatus IS NOT NULL) AS old_nonnull,SUM(wh_rainBatteryStatus IS NOT NULL) AS wh_nonnull,SUM(old_rainBatteryStatus IS NOT NULL AND wh_rainBatteryStatus IS NOT NULL AND old_rainBatteryStatus<=>wh_rainBatteryStatus) AS paired_equal,SUM(old_rainBatteryStatus IS NOT NULL AND wh_rainBatteryStatus IS NOT NULL AND NOT(old_rainBatteryStatus<=>wh_rainBatteryStatus)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'rainRate' AS field_name,COUNT(*) AS source_only_rows,SUM(old_rainRate IS NOT NULL) AS old_nonnull,SUM(wh_rainRate IS NOT NULL) AS wh_nonnull,SUM(old_rainRate IS NOT NULL AND wh_rainRate IS NOT NULL AND old_rainRate<=>wh_rainRate) AS paired_equal,SUM(old_rainRate IS NOT NULL AND wh_rainRate IS NOT NULL AND NOT(old_rainRate<=>wh_rainRate)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'referenceVoltage' AS field_name,COUNT(*) AS source_only_rows,SUM(old_referenceVoltage IS NOT NULL) AS old_nonnull,SUM(wh_referenceVoltage IS NOT NULL) AS wh_nonnull,SUM(old_referenceVoltage IS NOT NULL AND wh_referenceVoltage IS NOT NULL AND old_referenceVoltage<=>wh_referenceVoltage) AS paired_equal,SUM(old_referenceVoltage IS NOT NULL AND wh_referenceVoltage IS NOT NULL AND NOT(old_referenceVoltage<=>wh_referenceVoltage)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'rxCheckPercent' AS field_name,COUNT(*) AS source_only_rows,SUM(old_rxCheckPercent IS NOT NULL) AS old_nonnull,SUM(wh_rxCheckPercent IS NOT NULL) AS wh_nonnull,SUM(old_rxCheckPercent IS NOT NULL AND wh_rxCheckPercent IS NOT NULL AND old_rxCheckPercent<=>wh_rxCheckPercent) AS paired_equal,SUM(old_rxCheckPercent IS NOT NULL AND wh_rxCheckPercent IS NOT NULL AND NOT(old_rxCheckPercent<=>wh_rxCheckPercent)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilMoist1' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilMoist1 IS NOT NULL) AS old_nonnull,SUM(wh_soilMoist1 IS NOT NULL) AS wh_nonnull,SUM(old_soilMoist1 IS NOT NULL AND wh_soilMoist1 IS NOT NULL AND old_soilMoist1<=>wh_soilMoist1) AS paired_equal,SUM(old_soilMoist1 IS NOT NULL AND wh_soilMoist1 IS NOT NULL AND NOT(old_soilMoist1<=>wh_soilMoist1)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilMoist2' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilMoist2 IS NOT NULL) AS old_nonnull,SUM(wh_soilMoist2 IS NOT NULL) AS wh_nonnull,SUM(old_soilMoist2 IS NOT NULL AND wh_soilMoist2 IS NOT NULL AND old_soilMoist2<=>wh_soilMoist2) AS paired_equal,SUM(old_soilMoist2 IS NOT NULL AND wh_soilMoist2 IS NOT NULL AND NOT(old_soilMoist2<=>wh_soilMoist2)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilMoist3' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilMoist3 IS NOT NULL) AS old_nonnull,SUM(wh_soilMoist3 IS NOT NULL) AS wh_nonnull,SUM(old_soilMoist3 IS NOT NULL AND wh_soilMoist3 IS NOT NULL AND old_soilMoist3<=>wh_soilMoist3) AS paired_equal,SUM(old_soilMoist3 IS NOT NULL AND wh_soilMoist3 IS NOT NULL AND NOT(old_soilMoist3<=>wh_soilMoist3)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilTemp1' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilTemp1 IS NOT NULL) AS old_nonnull,SUM(wh_soilTemp1 IS NOT NULL) AS wh_nonnull,SUM(old_soilTemp1 IS NOT NULL AND wh_soilTemp1 IS NOT NULL AND old_soilTemp1<=>wh_soilTemp1) AS paired_equal,SUM(old_soilTemp1 IS NOT NULL AND wh_soilTemp1 IS NOT NULL AND NOT(old_soilTemp1<=>wh_soilTemp1)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilTemp2' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilTemp2 IS NOT NULL) AS old_nonnull,SUM(wh_soilTemp2 IS NOT NULL) AS wh_nonnull,SUM(old_soilTemp2 IS NOT NULL AND wh_soilTemp2 IS NOT NULL AND old_soilTemp2<=>wh_soilTemp2) AS paired_equal,SUM(old_soilTemp2 IS NOT NULL AND wh_soilTemp2 IS NOT NULL AND NOT(old_soilTemp2<=>wh_soilTemp2)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilTemp3' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilTemp3 IS NOT NULL) AS old_nonnull,SUM(wh_soilTemp3 IS NOT NULL) AS wh_nonnull,SUM(old_soilTemp3 IS NOT NULL AND wh_soilTemp3 IS NOT NULL AND old_soilTemp3<=>wh_soilTemp3) AS paired_equal,SUM(old_soilTemp3 IS NOT NULL AND wh_soilTemp3 IS NOT NULL AND NOT(old_soilTemp3<=>wh_soilTemp3)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi
ORDER BY utc_quarter,old_interval,wh_interval,field_name\n